draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // owner
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 15, H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 15, H/2 + 45);
  ctx.stroke();

  // dog
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 30*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30*Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 50 + 30*Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30*Math.sin(t), H/2 + 30);
  ctx.lineTo(W/2 + 35 + 30*Math.sin(t), H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30*Math.sin(t), H/2 + 30);
  ctx.lineTo(W/2 + 65 + 30*Math.sin(t), H/2 + 45);
  ctx.stroke();

  // danger
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 30*Math.cos(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 30*Math.cos(t), H/2 + 20);
  ctx.lineTo(W/2 - 50 + 30*Math.cos(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 30*Math.cos(t), H/2 + 30);
  ctx.lineTo(W/2 - 65 + 30*Math.cos(t), H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 30*Math.cos(t), H/2 + 30);
  ctx.lineTo(W/2 - 35 + 30*Math.cos(t), H/2 + 45);
  ctx.stroke();

  ctx.restore();
}
